def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    v4 = vars["v4"]
    v5 = vars["v5"]

    total = v1 + v2 + v3 + v4 + v5

    return {
        "value": total,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "v4": v4,
            "v5": v5,
            "total": total,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
